sys_ui_action.script:
/**
 * Client half of the one-job-at-a-time guard. Onclick: startExportMatchingWorkloadsForConfig()
 *
 * In this field rather than in `client_script_v2`, because that field is an empty stub on every
 * UI Action in this application and nothing reads it. Both halves share the Script field, which
 * is the whole reason the server half below is behind a `typeof window` guard.
 *
 * Purely to save a round trip that would end in an error message: the check that actually
 * enforces the rule runs on the server immediately before the job record is inserted, because
 * two people clicking within the same second both pass this one. Never treat this as the guard.
 *
 * GlideAjax is asynchronous, so the click always returns false and the form is submitted from
 * the callback rather than by returning true.
 */
function startExportMatchingWorkloadsForConfig() {
    var check = new GlideAjax('x_illu2_illumio.IllumioUtilsAJAX');
    check.addParam('sysparm_name', 'hasRunningJob');
    // Scopes the check to this PCE Configuration, so a job on a different one no longer greys
    // this out. Must match what the server half passes, or the two halves disagree and the
    // client waves through something the server then refuses.
    check.addParam('sysparm_config_sys_id', g_form.getUniqueValue());

    check.getXMLAnswer(function(answer) {
        var response;

        try {
            response = answer ? JSON.parse(answer) : { running: false };
        } catch (ex) {
            // Never leave the click doing nothing. An unreadable answer means the guard could
            // not be evaluated, and the server repeats the check anyway.
            response = { running: false };
        }

        if (response.running) {
            // Names the blocking job, because the action the user needs is usually to cancel it.
            g_form.addErrorMessage(response.message);
            return;
        }

        gsftSubmit(null, g_form.getFormElement(), 'export_matching_workloads_for_config');
    });

    return false;
}

// Server half: a trigger, and nothing else.
//
// This used to run both phases inline in the browser request -- evaluate every active inclusion
// Sync Filter, render the whole CSV to a string, write it with GlideSysAttachment. At 200k
// workloads that string is ~120 MB and the transaction is minutes long, and the one-filter export
// had already moved off that shape in R25. It is the same job as that one now, with a different
// context: IllumioPreviewUtils evaluates every eligible filter, the scheduler runs it, and the
// MID Server assembles and compresses the file.
//
// Action name: export_matching_workloads_for_config (the client half submits it by that name).
if (typeof window === 'undefined') {
    // Declared inside the server guard for the same reason gs.include is: this Script
    // field is evaluated in the browser too, for the client half above, and IllumioLogger
    // is a server Script Include. At the top of the file it threw a ReferenceError on
    // every form load and stopped the form rendering.
    var illumioLogger = new IllumioLogger(null, 'Export Matching Workloads for Config');

    // Inside the server guard, not at the top of the file. This Script field is evaluated in
    // the browser too, for the client half above, and `gs` does not exist there -- a
    // top-level gs.include would throw a ReferenceError and kill the onclick handler.
    gs.include("IllumioConstants");

    var configSysId = current.getUniqueValue();
    var redirectUrl = current.getTableName() + '.do?sys_id=' + configSysId;

    try {
        var utils = new IllumioUtils();
        // Scoped to this PCE Configuration. It was instance-wide, which was propping up two
        // sweeps that deleted anything they did not own -- both fixed, see getRunningJob.
        var runningJob = utils.getRunningJob(configSysId);

        if (runningJob) {
            // The authoritative check. The client half ran the same one before submitting, but
            // that was a different transaction and anything could have started since.
            //
            // The refusal gets a job record of its own, inserted already failed so it never
            // counts as running. There is nowhere else to log it -- you cannot write to the log
            // of a job you declined to create -- and without it a user reporting "the button
            // does nothing" leaves no trace to look at.
            var message = utils.describeRunningJob(runningJob);

            var refusedGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
            refusedGr.initialize();
            refusedGr.job_owner = gs.getUser().getID();
            refusedGr.job_type = 'preview';
            refusedGr.job_status = 'failed';
            refusedGr.job_started = new GlideDateTime();
            refusedGr.job_completed = new GlideDateTime();
            refusedGr.current_operation = 'Preview refused';
            refusedGr.illumio_pce_configuration = configSysId;
            refusedGr.logs = 'Inclusion preview requested for PCE Configuration "' +
                current.getValue('name') + '" and refused. ' + message;
            refusedGr.insert();

            gs.addErrorMessage(message);
            action.setRedirectURL(redirectUrl);

        } else {
            var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
            jobGr.initialize();
            jobGr.job_owner = gs.getUser().getID();
            jobGr.job_type = 'preview';
            jobGr.job_status = 'running';
            jobGr.job_started = new GlideDateTime();
            jobGr.current_operation = 'Preparing preview';
            jobGr.illumio_pce_configuration = configSysId;
            jobGr.logs = 'Inclusion preview requested for PCE Configuration "' +
                current.getValue('name') + '".';
            var jobSysId = jobGr.insert();
            // From here on the job record exists, so anything this action logs -- including
            // an exception out of the block below -- lands under the same job id the
            // scheduler half will use.
            illumioLogger.setContext(jobSysId);

            if (gs.nil(jobSysId)) {
                gs.addErrorMessage('Failed to create the scheduled job for this preview.');
            } else {
                // parm2 carries what the job record cannot: the scheduled jobs table has a PCE
                // Configuration reference but no generic target, and the preview types differ by
                // which record they attach to as well as by which filters they evaluate.
                var context = JSON.stringify({
                    type: new IllumioPreviewUtils().TYPE_CONFIG_EXPORT,
                    table: current.getTableName(),
                    sysId: configSysId
                });

                gs.eventQueueScheduled('x_illu2_illumio.start_preview',
                    jobGr, jobSysId, context, new GlideDateTime());

                gs.addInfoMessage('Preview job started. The CSV will be attached to this record ' +
                    'when it completes. Track progress in Scheduled Jobs.');
            }

            action.setRedirectURL(redirectUrl);
        }
    } catch (ex) {
        illumioLogger.error('Exception: ' + ex);
        gs.addErrorMessage('Error starting the preview: ' + ex);
        action.setRedirectURL(redirectUrl);
    }
}
